cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" roadmap list --focus AJC.pic0av --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
def walk(its,depth=0):
    for it in its:
        print('  '*depth, it['id'],'|',it.get('status'),'| owner=',repr(it.get('owner')))
        print('  '*depth,'   detail:',(it.get('detail') or '')[:600])
        print('  '*depth,'   strategy:',(it.get('strategy') or '')[:900])
        for k in ('children','items'):
            if it.get(k): walk(it[k],depth+1)
walk(d.get('items',[]))
"
